input.newString:
  updateStatus(id: number, status: Order["status"]): void {
    this.db.prepare("UPDATE orders SET status = ? WHERE id = ?").run(status, id);
  }

  /**
   * Applies a coupon to an order and records the redemption, atomically.
   * Updates the order, inserts a coupon_redemptions row and increments the
   * coupon usage count; rolls back everything if any statement fails.
   */
  applyCoupon(
    orderId: number,
    couponCode: string,
    discountCents: number,
    finalAmountCents: number,
    createdAt: string,
  ): void {
    this.db.exec("BEGIN");
    try {
      this.db
        .prepare("UPDATE orders SET discount_cents = ?, final_amount_cents = ?, coupon_code = ? WHERE id = ?")
        .run(discountCents, finalAmountCents, couponCode, orderId);
      this.db
        .prepare("INSERT INTO coupon_redemptions (order_id, coupon_code, discount_cents, created_at) VALUES (?, ?, ?, ?)")
        .run(orderId, couponCode, discountCents, createdAt);
      this.db.prepare("UPDATE coupons SET used_count = used_count + 1 WHERE code = ?").run(couponCode);
      this.db.exec("COMMIT");
    } catch (e) {
      this.db.exec("ROLLBACK");
      throw e;
    }
  }
}

