import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";

const NOW = "2026-10-01T08:00:00Z";
const fixedClock = () => new Date(NOW);

function newApp(): App {
  return createApp({ clock: fixedClock });
}

function createCoupon(app: App, overrides: Record<string, unknown> = {}): any {
  const res = app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...overrides,
  });
  expect(res.status).toBe(201);
  return res.body;
}

function createOrder(app: App, amountCents: number): any {
  const res = app.request("POST", "/orders", { customer: "alice", amountCents });
  expect(res.status).toBe(201);
  return res.body;
}

function apply(app: App, id: number, couponCode: unknown) {
  return app.request("POST", `/orders/${id}/apply-coupon`, { couponCode });
}

function redemptionCount(app: App, orderId: number, code: string): number {
  const row = app.db
    .prepare("SELECT COUNT(*) AS n FROM coupon_redemptions WHERE order_id = ? AND coupon_code = ?")
    .get(orderId, code) as { n: number };
  return row.n;
}

describe("apply coupon: discounts", () => {
  it("AC-01 percent reduces the amount", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2000, finalAmountCents: 8000 });
  });

  it("AC-02 fixed reduces the amount", () => {
    const app = newApp();
    createCoupon(app, { code: "FIX1500", type: "FIXED", value: 1500 });
    const order = createOrder(app, 10000);
    expect(apply(app, order.id, "FIX1500").body).toMatchObject({ discountCents: 1500, finalAmountCents: 8500 });
  });

  it("AC-03 uncapped percent can exceed the per-order hard cap check is 20000 > 10000 so capped", () => {
    const app = newApp();
    createCoupon(app, { code: "BIG20", type: "PERCENT", value: 20, maxDiscountCents: null });
    const order = createOrder(app, 100000);
    expect(apply(app, order.id, "BIG20").body).toMatchObject({ discountCents: 10000, finalAmountCents: 90000 });
  });

  it("AC-04 fixed larger than the amount discounts to zero", () => {
    const app = newApp();
    createCoupon(app, { code: "FIX3000", type: "FIXED", value: 3000 });
    const order = createOrder(app, 1000);
    expect(apply(app, order.id, "FIX3000").body).toMatchObject({ discountCents: 1000, finalAmountCents: 0 });
  });

  it("AC-05 percent rounds down", () => {
    const app = newApp();
    createCoupon(app, { code: "P15", type: "PERCENT", value: 15 });
    const order = createOrder(app, 999);
    expect(apply(app, order.id, "P15").body).toMatchObject({ discountCents: 149, finalAmountCents: 850 });
  });

  it("AC-06 amount equal to the minimum is accepted", () => {
    const app = newApp();
    createCoupon(app, { code: "MIN1000", type: "FIXED", value: 100, minAmountCents: 1000 });
    const order = createOrder(app, 1000);
    expect(apply(app, order.id, "MIN1000").status).toBe(200);
  });

  it("caps a percent discount at maxDiscountCents", () => {
    const app = newApp();
    createCoupon(app, { code: "CAP25", type: "PERCENT", value: 20, maxDiscountCents: 2500 });
    const order = createOrder(app, 100000);
    expect(apply(app, order.id, "CAP25").body).toMatchObject({ discountCents: 2500 });
  });

  it("never discounts more than 10000 cents", () => {
    const app = newApp();
    createCoupon(app, { code: "HUGE", type: "FIXED", value: 50000 });
    const order = createOrder(app, 50000);
    expect(apply(app, order.id, "HUGE").body).toMatchObject({ discountCents: 10000 });
  });
});

describe("apply coupon: validation and errors", () => {
  it("rejects a missing couponCode with INVALID_REQUEST", () => {
    const app = newApp();
    const order = createOrder(app, 10000);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, {});
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("INVALID_REQUEST");
  });

  it("rejects a non-string couponCode with INVALID_REQUEST", () => {
    const app = newApp();
    const order = createOrder(app, 10000);
    expect((apply(app, order.id, 123).body as any).error.code).toBe("INVALID_REQUEST");
  });

  it("rejects a blank couponCode with INVALID_REQUEST", () => {
    const app = newApp();
    const order = createOrder(app, 10000);
    expect((apply(app, order.id, "   ").body as any).error.code).toBe("INVALID_REQUEST");
  });

  it("returns ORDER_NOT_FOUND for an unknown order", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const res = apply(app, 999, "SAVE20");
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("returns ORDER_NOT_PENDING for a paid order", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const order = createOrder(app, 10000);
    app.request("POST", `/orders/${order.id}/pay`);
    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("returns COUPON_ALREADY_APPLIED on a second application", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    createCoupon(app, { code: "OTHER", type: "FIXED", value: 100 });
    const order = createOrder(app, 10000);
    expect(apply(app, order.id, "SAVE20").status).toBe(200);
    const second = apply(app, order.id, "OTHER");
    expect(second.status).toBe(409);
    expect((second.body as any).error.code).toBe("COUPON_ALREADY_APPLIED");
    expect(app.request("GET", `/orders/${order.id}`).body).toMatchObject({ couponCode: "SAVE20", discountCents: 2000 });
  });

  it("rejects reusing the same coupon with COUPON_ALREADY_APPLIED", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const order = createOrder(app, 10000);
    apply(app, order.id, "SAVE20");
    expect((apply(app, order.id, "SAVE20").body as any).error.code).toBe("COUPON_ALREADY_APPLIED");
  });

  it("returns COUPON_NOT_FOUND for an unknown coupon", () => {
    const app = newApp();
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, "NOPE");
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("returns COUPON_INACTIVE for a disabled coupon", () => {
    const app = newApp();
    createCoupon(app, { code: "OFF", status: "DISABLED" });
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, "OFF");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_INACTIVE");
  });

  it("returns COUPON_NOT_YET_VALID before validFrom", () => {
    const app = newApp();
    createCoupon(app, { code: "FUTURE", validFrom: "2026-12-01T00:00:00Z" });
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, "FUTURE");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_NOT_YET_VALID");
  });

  it("returns COUPON_EXPIRED at validUntil", () => {
    const app = newApp();
    createCoupon(app, { code: "EXP", validUntil: NOW });
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, "EXP");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("accepts the coupon exactly at validFrom", () => {
    const app = newApp();
    createCoupon(app, { code: "START", validFrom: NOW });
    const order = createOrder(app, 10000);
    expect(apply(app, order.id, "START").status).toBe(200);
  });

  it("returns COUPON_USAGE_EXHAUSTED at the usage limit", () => {
    const app = newApp();
    createCoupon(app, { code: "ONCE", type: "FIXED", value: 100, usageLimit: 1 });
    const first = createOrder(app, 10000);
    const second = createOrder(app, 10000);
    expect(apply(app, first.id, "ONCE").status).toBe(200);
    const res = apply(app, second.id, "ONCE");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_USAGE_EXHAUSTED");
  });

  it("returns MINIMUM_NOT_MET below the minimum amount", () => {
    const app = newApp();
    createCoupon(app, { code: "MIN5000", type: "FIXED", value: 100, minAmountCents: 5000 });
    const order = createOrder(app, 4999);
    const res = apply(app, order.id, "MIN5000");
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("MINIMUM_NOT_MET");
  });

  it("leaves the database unchanged on rejection", () => {
    const app = newApp();
    createCoupon(app, { code: "MIN5000", type: "FIXED", value: 100, minAmountCents: 5000 });
    const order = createOrder(app, 1000);
    const before = app.request("GET", `/orders/${order.id}`).body;
    apply(app, order.id, "MIN5000");
    expect(app.request("GET", `/orders/${order.id}`).body).toEqual(before);
    expect(app.request("GET", "/coupons/MIN5000").body).toMatchObject({ usedCount: 0 });
    expect(redemptionCount(app, order.id, "MIN5000")).toBe(0);
  });
});

describe("apply coupon: normalization, persistence and response", () => {
  it("AC-10 trims and uppercases the code", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, " save20 ");
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ couponCode: "SAVE20" });
  });

  it("AC-09 increments usedCount and records a redemption", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const order = createOrder(app, 10000);
    apply(app, order.id, "SAVE20");
    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
    expect(redemptionCount(app, order.id, "SAVE20")).toBe(1);
  });

  it("AC-14 response equals GET /orders/:id", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const order = createOrder(app, 10000);
    const res = apply(app, order.id, "SAVE20");
    expect(res.status).toBe(200);
    expect(res.body).toEqual(app.request("GET", `/orders/${order.id}`).body);
  });

  it("keeps the order status PENDING after applying", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const order = createOrder(app, 10000);
    expect(apply(app, order.id, "SAVE20").body).toMatchObject({ status: "PENDING" });
  });
});

